# All rights reserved. Unauthorized copying, distribution, or modification of this script is prohibited.

$ErrorActionPreference = "Stop"

# ============================================================
# CONFIG
# ============================================================

$MainDir            = "C:\Windows\System32\Acceleron"
$BaseDir            = Join-Path $MainDir "Appblocker"
$CertDir            = Join-Path $MainDir "Certificate"

$ExeWrapperPath     = Join-Path $BaseDir "Appblocker.exe"
$ServicePath        = Join-Path $BaseDir "svcapp.exe"
$JsonPath           = Join-Path $BaseDir "Blocked-apps.json"
$CertPath           = Join-Path $CertDir "AcceleronCertificate.cer"

$RegPath            = "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\AppBlocker"

# Calculate folder size in KB
$EstimatedSize = [math]::Ceiling(((Get-ChildItem $BaseDir -Recurse -File | Measure-Object Length -Sum).Sum) / 1KB)

$UninstallCmd = 'powershell.exe -ExecutionPolicy Bypass -NoProfile -Command "$ErrorActionPreference = ''SilentlyContinue''; Stop-Process -Name appblocker,svcapp -Force -ErrorAction SilentlyContinue; Start-Sleep -Seconds 2; schtasks.exe /Delete /TN ''App Blocker - Interactive User'' /F; Remove-ItemProperty -Path ''HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run'' -Name ''AppBlockerWatchdog'' -ErrorAction SilentlyContinue; Remove-Item -Path ''HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\AppBlocker'' -Recurse -Force -ErrorAction SilentlyContinue; Remove-Item -Path ''C:\Windows\System32\Acceleron\Appblocker'' -Recurse -Force -ErrorAction SilentlyContinue"'

$PinnedThumbprint   = "C9C559D901C9B31C90AF64D0D20A091013A3D4C3"

$IsSystem           = ([Security.Principal.WindowsIdentity]::GetCurrent().IsSystem)
$IsAdmin            = ([Security.Principal.WindowsPrincipal] `
                      [Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)

# ============================================================
# ENSURE BASE DIRECTORY
# ============================================================

# Create base directory if not exists
if (-not (Test-Path $BaseDir)) {
    New-Item -Path $BaseDir -ItemType Directory -Force | Out-Null
}

# Create certificate directory if not exists
if (-not (Test-Path $CertDir)) {
    New-Item -Path $CertDir -ItemType Directory -Force | Out-Null
}

# ============================================================
# CLEAN OLD TASKS (SAFE)
# ============================================================
Get-ScheduledTask -TaskName "App Blocker Policy","BlockAnyDeskTask Policy" -ErrorAction SilentlyContinue | Unregister-ScheduledTask -Confirm:$false
Get-Process -Name appblocker,svcapp -ErrorAction SilentlyContinue | Stop-Process -Force
Remove-Item $ExeWrapperPath, $ServicePath, $CertPath -Force -ErrorAction SilentlyContinue
Remove-Item "C:\Windows\Block-Anydesk.ps1","C:\Windows\Block-WindowsStore.ps1","C:\Windows\RunHidden.vbs","C:\Windows\RunHidden-Store.vbs" -Force -ErrorAction SilentlyContinue

# ============================================================
# EMBEDDED BINARIES (BASE64)
# ============================================================

$CertBase64 = @'

'@

$AppBlockerExeBase64 = @'

'@

$ServiceBase64 = @'

'@

$JsonContent = @'
{
  "apps": [
    {
      "name": "Windows Store",
      "blockMessage": "Windows Store has been blocked by your Administrator.",
      "matchType": "ProcessName",
      "matchValue": "WinStore.App",
      "adminExempt": true
    },
    {
      "name": "TeamViewer",
      "blockMessage": "TeamViewer has been blocked by your Administrator.",
      "matchType": "ProductName",
      "matchValue": "TeamViewer",
      "adminExempt": false
    },
	{
      "name": "Powershell",
      "blockMessage": "Powershell has been blocked by your Administrator.",
      "matchType": "ProductName",
      "matchValue": "PowerShell",
      "adminExempt": true
    }
  ]
}
'@

# ============================================================
# DECODE EXEs
# ============================================================

$ExeBytes = [Convert]::FromBase64String($AppBlockerExeBase64)
$ServiceExeBytes = [Convert]::FromBase64String($ServiceBase64)

# ============================================================
# WRITE + TRUST CERTIFICATE (SYSTEM ONLY)
# ============================================================

if ($IsSystem -or $IsAdmin) {

    if (-not (Test-Path $CertPath)) {
        [IO.File]::WriteAllBytes(
            $CertPath,
            [Convert]::FromBase64String($CertBase64)
        )
    }

    foreach ($store in @(
        "Root",
        "TrustedPublisher"
    )) {
        if (-not (certutil -store $store | Select-String $PinnedThumbprint)) {
            & certutil.exe -addstore $store $CertPath | Out-Null
        }
    }
}

# ============================================================
# WRITE EXE WRAPPER
# ============================================================

[IO.File]::WriteAllBytes(
    $ExeWrapperPath,
    $ExeBytes
)

$Sig = Get-AuthenticodeSignature -FilePath $ExeWrapperPath

if (
    -not $Sig.SignerCertificate -or
    $Sig.SignerCertificate.Thumbprint -ne $PinnedThumbprint -or
    $Sig.Status -in @(
        'HashMismatch',
        'NotSigned',
        'UnknownError'
    )
) {
    throw "Appblocker.exe signature validation failed. Status: $($Sig.Status)"
}

# ============================================================
# WRITE SERVICE EXE
# ============================================================

[IO.File]::WriteAllBytes(
    $ServicePath,
    $ServiceExeBytes
)

$Sig = Get-AuthenticodeSignature -FilePath $ServicePath

if (
    -not $Sig.SignerCertificate -or
    $Sig.SignerCertificate.Thumbprint -ne $PinnedThumbprint -or
    $Sig.Status -in @(
        'HashMismatch',
        'NotSigned',
        'UnknownError'
    )
) {
    throw "svcapp.exe signature validation failed. Status: $($Sig.Status)"
}

# ============================================================
# WRITE JSON CONFIG
# ============================================================

Set-Content -Path $JsonPath -Value $JsonContent -Encoding UTF8 -Force

# ============================================================
# Install App Blocker
# ============================================================

# -----------------------
# Register application
# -----------------------

$AppName          = "Application Blocker"
$AppVersion       = if (Test-Path $ExeWrapperPath) { (Get-Item $ExeWrapperPath).VersionInfo.FileVersion } else { $null }

New-Item -Path $RegPath -Force | Out-Null

New-ItemProperty $RegPath DisplayName      -Value $AppName        -PropertyType String -Force | Out-Null
New-ItemProperty $RegPath DisplayVersion   -Value $AppVersion     -PropertyType String -Force | Out-Null
New-ItemProperty $RegPath Publisher        -Value "Acceleron Solutions Pvt Ltd." -PropertyType String -Force | Out-Null
New-ItemProperty $RegPath InstallLocation  -Value $BaseDir        -PropertyType String -Force | Out-Null
New-ItemProperty $RegPath DisplayIcon      -Value $ExeWrapperPath -PropertyType String -Force | Out-Null
New-ItemProperty $RegPath NoModify         -Value 1               -PropertyType DWord -Force | Out-Null
New-ItemProperty $RegPath NoRepair         -Value 1               -PropertyType DWord -Force | Out-Null
New-ItemProperty $RegPath EstimatedSize    -Value $EstimatedSize  -PropertyType DWord -Force | Out-Null
New-ItemProperty $RegPath Comments         -Value "Bishnu Prasad Panigrahi" -PropertyType String -Force | Out-Null
New-ItemProperty $RegPath UninstallString  -Value $UninstallCmd  -PropertyType String -Force | Out-Null

# ------------------------------------------------------------
# Windows API
# ------------------------------------------------------------

if (-not ("AcceleronAppBlocker.NativeMethods" -as [type])) {

Add-Type @'
using System;
using System.Runtime.InteropServices;

namespace AcceleronAppBlocker
{
    public static class NativeMethods
    {
        [DllImport("kernel32.dll", SetLastError = true)]
        public static extern uint WTSGetActiveConsoleSessionId();

        [DllImport("wtsapi32.dll", SetLastError = true)]
        public static extern bool WTSQueryUserToken(
            UInt32 SessionId,
            out IntPtr phToken
        );

        [DllImport("userenv.dll", SetLastError = true)]
        public static extern bool CreateEnvironmentBlock(
            out IntPtr lpEnvironment,
            IntPtr hToken,
            bool bInherit
        );

        [DllImport("userenv.dll", SetLastError = true)]
        public static extern bool DestroyEnvironmentBlock(
            IntPtr lpEnvironment
        );

        [DllImport("advapi32.dll",
            SetLastError = true,
            CharSet = CharSet.Unicode)]
        public static extern bool CreateProcessAsUser(
            IntPtr hToken,
            string lpApplicationName,
            string lpCommandLine,
            IntPtr lpProcessAttributes,
            IntPtr lpThreadAttributes,
            bool bInheritHandles,
            UInt32 dwCreationFlags,
            IntPtr lpEnvironment,
            string lpCurrentDirectory,
            ref STARTUPINFO lpStartupInfo,
            out PROCESS_INFORMATION lpProcessInformation
        );

        [DllImport("kernel32.dll", SetLastError = true)]
        public static extern bool CloseHandle(IntPtr hObject);

        [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)]
        public struct STARTUPINFO
        {
            public UInt32 cb;
            public string lpReserved;
            public string lpDesktop;
            public string lpTitle;
            public UInt32 dwX;
            public UInt32 dwY;
            public UInt32 dwXSize;
            public UInt32 dwYSize;
            public UInt32 dwXCountChars;
            public UInt32 dwYCountChars;
            public UInt32 dwFillAttribute;
            public UInt32 dwFlags;
            public UInt16 wShowWindow;
            public UInt16 cbReserved2;
            public IntPtr lpReserved2;
            public IntPtr hStdInput;
            public IntPtr hStdOutput;
            public IntPtr hStdError;
        }

        [StructLayout(LayoutKind.Sequential)]
        public struct PROCESS_INFORMATION
        {
            public IntPtr hProcess;
            public IntPtr hThread;
            public UInt32 dwProcessId;
            public UInt32 dwThreadId;
        }
    }
}
'@

}

# ------------------------------------------------------------
# Get current script user
# ------------------------------------------------------------

$currentIdentity = [System.Security.Principal.WindowsIdentity]::GetCurrent()

if ($null -eq $currentIdentity) {
    throw "Unable to determine current script user."
}

$currentAccount = $currentIdentity.Name
$currentToken   = $currentIdentity.Token

if ([string]::IsNullOrWhiteSpace($currentAccount) -or
    $currentToken -eq [IntPtr]::Zero) {
    throw "Unable to determine current user/token."
}

# ------------------------------------------------------------
# Try active logged-in user's token first
# ------------------------------------------------------------

$sessionId = [AcceleronAppBlocker.NativeMethods]::WTSGetActiveConsoleSessionId()

$userToken = [IntPtr]::Zero
$account   = $null
$usedFallback = $false

if ($sessionId -ne [UInt32]::MaxValue) {

    if ([AcceleronAppBlocker.NativeMethods]::WTSQueryUserToken(
        $sessionId,
        [ref]$userToken
    )) {
        try {
            $account = (Get-CimInstance Win32_ComputerSystem -Property UserName).UserName
        }
        catch {
            $account = $null
        }

        if ([string]::IsNullOrWhiteSpace($account)) {
            [AcceleronAppBlocker.NativeMethods]::CloseHandle($userToken)
            $userToken = [IntPtr]::Zero
        }
    }
}

# ------------------------------------------------------------
# Fallback:
# Use the user who executed this script
# ------------------------------------------------------------

if ($userToken -eq [IntPtr]::Zero) {

    $userToken = $currentToken
    $account = $currentAccount
    $usedFallback = $true
}

# ------------------------------------------------------------
# Get username
# ------------------------------------------------------------

$username = $account.Split('\')[-1]

# ------------------------------------------------------------
# Get display name
# ------------------------------------------------------------

$displayName = $username

try {
    $principalContextType = [System.DirectoryServices.AccountManagement.ContextType]::Domain

    $principal = [System.DirectoryServices.AccountManagement.UserPrincipal]::FindByIdentity(
        $principalContextType,
        $account
    )

    if ($null -ne $principal -and
        -not [string]::IsNullOrWhiteSpace($principal.DisplayName)) {

        $displayName = $principal.DisplayName
    }
}
catch {
    $displayName = $username
}

if ([string]::IsNullOrWhiteSpace($displayName)) {
    $displayName = $username
}

# ------------------------------------------------------------
# Create user environment
# ------------------------------------------------------------

$environment = [IntPtr]::Zero

if (-not [AcceleronAppBlocker.NativeMethods]::CreateEnvironmentBlock(
    [ref]$environment,
    $userToken,
    $false
)) {

    if (-not $usedFallback) {
        [AcceleronAppBlocker.NativeMethods]::CloseHandle($userToken)
    }

    throw "Unable to create user environment."
}

# ------------------------------------------------------------
# Startup information
# ------------------------------------------------------------

$si = New-Object 'AcceleronAppBlocker.NativeMethods+STARTUPINFO'

$si.cb = [Runtime.InteropServices.Marshal]::SizeOf($si)

$si.lpDesktop = "winsta0\default"

$pi = New-Object 'AcceleronAppBlocker.NativeMethods+PROCESS_INFORMATION'

$CREATE_UNICODE_ENVIRONMENT = 0x00000400

# ------------------------------------------------------------
# Start App Blocker as selected user
# ------------------------------------------------------------

$success = [AcceleronAppBlocker.NativeMethods]::CreateProcessAsUser(
    $userToken,
    $ServicePath,
    $null,
    [IntPtr]::Zero,
    [IntPtr]::Zero,
    $false,
    $CREATE_UNICODE_ENVIRONMENT,
    $environment,
    $BaseDir,
    [ref]$si,
    [ref]$pi
)

$errorCode = 0

if (-not $success) {
    $errorCode = [Runtime.InteropServices.Marshal]::GetLastWin32Error()
}

# ------------------------------------------------------------
# Cleanup
# ------------------------------------------------------------

$null = [AcceleronAppBlocker.NativeMethods]::DestroyEnvironmentBlock($environment)

# Only close the WTS token.
# For fallback, the token belongs to the current WindowsIdentity.
if (-not $usedFallback) {
    $null = [AcceleronAppBlocker.NativeMethods]::CloseHandle($userToken)
}

if (-not $success) {
    throw "Unable to start App Blocker. Win32 error: $errorCode"
}

$null = [AcceleronAppBlocker.NativeMethods]::CloseHandle($pi.hThread)
$null = [AcceleronAppBlocker.NativeMethods]::CloseHandle($pi.hProcess)

# ------------------------------------------------------------
# SCHEDULED TASK: APP BLOCKER (INTERACTIVE USER)
# ------------------------------------------------------------

# Generate correct timestamp
$startTime = (Get-Date).AddMinutes(1).ToString("yyyy-MM-ddTHH:mm:ss")

$TaskName = "App Blocker - Interactive User"
$tempXml  = "$env:TEMP\AppBlockerTask.xml"

# ---------------- CLEAN OLD TASK ----------------

Unregister-ScheduledTask -TaskName $TaskName -Confirm:$false -ErrorAction SilentlyContinue

# ---------------- CREATE XML ----------------

$xml = @"
<?xml version="1.0" encoding="UTF-16"?>
<Task version="1.2" xmlns="http://schemas.microsoft.com/windows/2004/02/mit/task">
  <RegistrationInfo>
    <Author>Acceleron</Author>
    <URI>\Application Blocker</URI>
  </RegistrationInfo>
  <Triggers>
    <TimeTrigger>
      <Repetition>
        <Interval>PT1M</Interval>
        <StopAtDurationEnd>false</StopAtDurationEnd>
      </Repetition>
      <StartBoundary>$startTime</StartBoundary>
      <Enabled>true</Enabled>
    </TimeTrigger>
    <LogonTrigger>
      <Enabled>true</Enabled>
    </LogonTrigger>
  </Triggers>
  <Principals>
    <Principal id="Author">
      <GroupId>S-1-5-4</GroupId>
      <RunLevel>HighestAvailable</RunLevel>
    </Principal>
  </Principals>
  <Settings>
    <MultipleInstancesPolicy>IgnoreNew</MultipleInstancesPolicy>
    <DisallowStartIfOnBatteries>true</DisallowStartIfOnBatteries>
    <StopIfGoingOnBatteries>true</StopIfGoingOnBatteries>
    <AllowHardTerminate>true</AllowHardTerminate>
    <StartWhenAvailable>true</StartWhenAvailable>
    <RunOnlyIfNetworkAvailable>false</RunOnlyIfNetworkAvailable>
    <IdleSettings>
      <StopOnIdleEnd>true</StopOnIdleEnd>
      <RestartOnIdle>false</RestartOnIdle>
    </IdleSettings>
    <AllowStartOnDemand>true</AllowStartOnDemand>
    <Enabled>true</Enabled>
    <Hidden>true</Hidden>
    <RunOnlyIfIdle>false</RunOnlyIfIdle>
    <WakeToRun>false</WakeToRun>
    <ExecutionTimeLimit>PT0S</ExecutionTimeLimit>
    <Priority>7</Priority>
  </Settings>
  <Actions Context="Author">
    <Exec>
      <Command>$ExeWrapperPath</Command>
    </Exec>
  </Actions>
</Task>
"@

# ---------------- SAVE XML ----------------

$xml | Out-File -FilePath $tempXml -Encoding Unicode

# ---------------- REGISTER TASK ----------------

$null = Register-ScheduledTask -TaskName $TaskName -Xml (Get-Content $tempXml | Out-String) -Force
# ---------------- CLEANUP ----------------

Remove-Item $tempXml -Force -ErrorAction SilentlyContinue
Get-Process -Name appblocker,svcapp -ErrorAction SilentlyContinue | Stop-Process -Force

# Trigger immediately after registration. The task only runs if an interactive
# user token is available; it cannot fall back to SYSTEM.
try {
    Start-ScheduledTask -TaskName $TaskName -ErrorAction Stop
    Start-Sleep -Seconds 3
} catch {
    # Write-Warning "Task is registered but could not start now. It will run at the next interactive logon. $($_.Exception.Message)"
}

# ------------------------------------------------------------
# Final output only
# ------------------------------------------------------------

# Clear applied Certificate
Remove-Item $CertDir -Recurse -Force -ErrorAction SilentlyContinue

Write-Host "Application Blocker started for - $displayName"